/**
 * The shipped nets and recorded runs, as live objects. `weights.ts` and
 * `bench-data.ts` are generated by `__train__.ts`; this is the only place
 * that reads them, so widgets and checks share one set of `Mlp` instances.
 */

import { Mlp } from './mlp';
import { DENOISER_WEIGHTS, HEURISTIC_WEIGHTS, POLICY_WEIGHTS, SAMPLER_WEIGHTS, TRAINING_META } from './weights';
import { BENCH_DATA } from './bench-data';
import type { BenchData } from './bench';

export { TRAINING_META };

export interface ShippedModels {
  sampler: Mlp;
  heuristic: Mlp;
  policy: Mlp;
  denoiser: Mlp;
}

let cache: ShippedModels | null = null;

/** Deserialize once; the nets are read-only from here on. */
export function loadModels(): ShippedModels {
  if (!cache) {
    cache = {
      sampler: Mlp.fromJSON(SAMPLER_WEIGHTS),
      heuristic: Mlp.fromJSON(HEURISTIC_WEIGHTS),
      policy: Mlp.fromJSON(POLICY_WEIGHTS),
      denoiser: Mlp.fromJSON(DENOISER_WEIGHTS),
    };
  }
  return cache;
}

/** JSON cannot carry +∞: unsolved runs were written with `cost: null`. */
function normalize(data: BenchData): BenchData {
  for (const suite of [data.suites.train, data.suites.heldout]) {
    for (const q of suite.queries) {
      for (const r of q.runs) if (r.cost === null || !Number.isFinite(r.cost)) r.cost = Infinity;
      if (q.incumbent === null || !Number.isFinite(q.incumbent)) q.incumbent = Infinity;
    }
  }
  return data;
}

/** The Board's recorded runs. */
export const BENCH: BenchData = normalize(BENCH_DATA);

/** The ε measured on the validation suite when the heuristic was trained — the number w22.2 deflates by. */
export const EPSILON_VALIDATION: number = TRAINING_META.epsilon.validation.epsilon;
